# Voted dominant first-row color wins; blank cells in output derived from three rows via most frequent nonzero value, ties choose larger/lower?
out=[]
for r in range(3):
 row=[]
 for c in range(6):
  vals=[g[3*r+i][c] for i in range(3)]
  counts={v:vals.count(v) for v in set(vals)}
  # Most frequent among nonzero; for tie choose topmost occurrence, except if no nonzero retain 0
  nonzero=[v for v in vals if v]
  if not nonzero: row.append(0)
  else:
   m=max(nonzero.count(v) for v in set(nonzero))
   row.append(next(v for v in nonzero if nonzero.count(v)==m))
 out.append(row)
print(out)
